package pe.com.dentalamericana.treatment;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="servicios")public class ServiceCatalog{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String codigo;@Column(nullable=false)private String nombre;@Column(nullable=false)private String categoria;private String descripcion;@Column(name="precio_base",nullable=false)private BigDecimal basePrice;@Column(name="sesiones_sugeridas",nullable=false)private int suggestedSessions;@Column(nullable=false)private boolean activo=true;protected ServiceCatalog(){}public Long getId(){return id;}public String getCode(){return codigo;}public String getName(){return nombre;}public String getCategory(){return categoria;}public String getDescription(){return descripcion;}public BigDecimal getBasePrice(){return basePrice;}public int getSuggestedSessions(){return suggestedSessions;}public boolean isActive(){return activo;}}
